UPDATE approval_definition SET name=#{name}, version=#{persistedVersion}, revision=#{revision}, status=#{status}, graph_json=CASE WHEN status='DRAFT' THEN #{graphJson} ELSE graph_json END, form_schema_json=#{schemaJson}, notification_texts_json=#{textsJson}, start_enabled=#{startEnabled},
    published_at=CASE WHEN #{status2}='PUBLISHED' THEN COALESCE(published_at, CURRENT_TIMESTAMP) ELSE published_at END,
    updated_at=CURRENT_TIMESTAMP WHERE tenant_id=#{tenantId} AND id=#{id} AND revision=#{expectedRevision}
